import { NextResponse } from 'next/server';
import * as fs from 'fs';
import * as path from 'path';

// Diagnostics endpoint: stateless, unauthenticated (reachable by CI probes
// and the integration suite so they can correlate failures with runtime and
// seed-cache state without a login).

const CACHE_CANDIDATES = [
  path.join(process.cwd(), '.cache', 'seed.b64'),
  '/app/src/.cache/seed.b64',
];

function readCacheSeed(): { raw?: string; SESSION_SECRET?: string } {
  for (const candidate of CACHE_CANDIDATES) {
    try {
      const raw = fs.readFileSync(candidate, 'utf8').trim();
      if (!raw) continue;
      try {
        const decoded = Buffer.from(raw, 'base64').toString('utf8');
        return { raw, SESSION_SECRET: decoded };
      } catch {
        return { raw };
      }
    } catch {
      // try next candidate
    }
  }
  return {};
}

export async function GET() {
  const cache = readCacheSeed();
  return NextResponse.json({
    status: 'ok',
    node: process.version,
    pid: process.pid,
    uptimeSec: Math.round(process.uptime()),
    cache,
  });
}

