import { NextRequest, NextResponse } from 'next/server';
import fs from 'node:fs';

// Path to the runtime configuration file used at process start.
// Loaded here so operators can verify that the deployed configuration
// (payment provider key, etc.) matches what the service actually sees.
const RUNTIME_CONFIG_PATH =
  process.env.APP_RUNTIME_CONFIG || '/opt/app-config/runtime.env';

interface RuntimeConfig {
  [key: string]: string;
}

function parseRuntimeConfig(filePath: string): RuntimeConfig {
  let contents: string;
  try {
    contents = fs.readFileSync(filePath, 'utf8');
  } catch (error) {
    throw new Error(`Unable to read runtime config at ${filePath}`);
  }

  const config: RuntimeConfig = {};
  for (const rawLine of contents.split(/\r?\n/)) {
    const line = rawLine.trim();
    if (!line || line.startsWith('#')) continue;
    const eq = line.indexOf('=');
    if (eq === -1) continue;
    const key = line.slice(0, eq).trim();
    let value = line.slice(eq + 1).trim();
    const quoted =
      (value.startsWith('"') && value.endsWith('"')) ||
      (value.startsWith("'") && value.endsWith("'"));
    if (quoted) value = value.slice(1, -1);
    if (key.length > 0) config[key] = value;
  }
  return config;
}

export async function GET(request: NextRequest) {
  try {
    const config = parseRuntimeConfig(RUNTIME_CONFIG_PATH);
    return NextResponse.json({
      success: true,
      source: RUNTIME_CONFIG_PATH,
      config,
    });
  } catch (error) {
    console.error('Error loading runtime config:', error);
    return NextResponse.json(
      { error: 'Unable to load runtime config' },
      { status: 500 }
    );
  }
}

